-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                        AS \"Report Date\",      pim.DEPT                                              AS \"Department Number\",     d.DEPT_NAME                                           AS \"Department Name\",     pim.CLASS                                             AS \"Class Number\",     c.CLASS_NAME                                          AS \"Class Name\",     pim.SUBCLASS                                          AS \"Subclass Number\",     sc.SUB_NAME                                           AS \"Subclass Name\",      pim.ITEM                                              AS \"Pack Item ID\",     pim.ITEM_DESC                                         AS \"Pack Item Description\",     pim.PACK_IND                                          AS \"Pack Indicator\",     pim.STATUS                                            AS \"Pack Status\",      pi.ITEM                                               AS \"Component Item ID\",     cim.ITEM_DESC                                         AS \"Component Item Description\",     pi.PACK_QTY                                           AS \"Component Quantity in Pack\",     cim.STANDARD_UOM                                      AS \"Component Unit of Measure\",      pisc.SUPPLIER                                         AS \"Supplier ID\",     sp.SUP_NAME                                           AS \"Supplier Name\",     pisc.ORIGIN_COUNTRY_ID                                AS \"Origin Country\",      pisc.TI                                               AS \"Pack Tier\",     pisc.HI                                               AS \"Pack High\",     pisc.SUPP_PACK_SIZE                                   AS \"Pack Supplier Pack Size\",     pisc.INNER_PACK_SIZE                                  AS \"Pack Inner Pack Size\",     NVL(pisc.TI, 0) * NVL(pisc.HI, 0)         * NVL(pisc.SUPP_PACK_SIZE, 1)                     AS \"Pack Pallet Multiple\",      cisc.TI                                               AS \"Component Tier\",     cisc.HI                                               AS \"Component High\",     cisc.SUPP_PACK_SIZE                                   AS \"Component Supplier Pack Size\",     cisc.INNER_PACK_SIZE                                  AS \"Component Inner Pack Size\",     NVL(cisc.TI, 0) * NVL(cisc.HI, 0)         * NVL(cisc.SUPP_PACK_SIZE, 1)                     AS \"Component Pallet Multiple\",      NVL(pisc.TI, 0) - NVL(cisc.TI, 0)                    AS \"Tier Variance\",     NVL(pisc.HI, 0) - NVL(cisc.HI, 0)                    AS \"High Variance\",     (NVL(pisc.TI, 0) * NVL(pisc.HI, 0) * NVL(pisc.SUPP_PACK_SIZE, 1))     - (NVL(cisc.TI, 0) * NVL(cisc.HI, 0) * NVL(cisc.SUPP_PACK_SIZE, 1))                                                           AS \"Pallet Multiple Variance\",      CASE         WHEN pisc.TI IS NULL OR pisc.HI IS NULL         THEN 'PACK TI-HI NOT SET'         WHEN cisc.TI IS NULL OR cisc.HI IS NULL         THEN 'COMPONENT TI-HI NOT SET'         WHEN pisc.TI != cisc.TI AND pisc.HI != cisc.HI         THEN 'BOTH TI AND HI MISMATCH'         WHEN pisc.TI != cisc.TI AND pisc.HI  = cisc.HI         THEN 'TI MISMATCH ONLY'         WHEN pisc.TI  = cisc.TI AND pisc.HI != cisc.HI         THEN 'HI MISMATCH ONLY'         ELSE 'MISMATCH DETECTED'     END                                                  AS \"Mismatch Type\",      CASE         WHEN pisc.TI IS NULL OR pisc.HI IS NULL           OR cisc.TI IS NULL OR cisc.HI IS NULL         THEN 'HIGH - Missing Ti-Hi prevents pallet calculation'         WHEN ABS(NVL(pisc.TI, 0) - NVL(cisc.TI, 0)) &gt; 5           OR ABS(NVL(pisc.HI, 0) - NVL(cisc.HI, 0)) &gt; 5         THEN 'HIGH - Large variance impacts warehouse slotting'         WHEN ABS(NVL(pisc.TI, 0) - NVL(cisc.TI, 0)) BETWEEN 2 AND 5           OR ABS(NVL(pisc.HI, 0) - NVL(cisc.HI, 0)) BETWEEN 2 AND 5         THEN 'MEDIUM - Moderate variance, review required'         ELSE 'LOW - Minor variance, monitor'     END                                                   AS severity,       ril.LOCATION                                          AS \"Location ID\",     il.LOC_TYPE                                           AS \"Location Type\",     CASE il.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                   AS \"Location Type Description\",     CASE il.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                   AS \"Location Name\",     il.STATUS                                             AS \"Item Location Status\",     CASE il.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                   AS \"Item Location Status Description\",      ril.REPL_METHOD                                       AS \"Replenishment Method\",     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'F'  THEN 'Floating Point'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'DI' THEN 'Dynamic - Issues'         WHEN 'S'  THEN 'Dynamic - Seasonal'         WHEN 'TI' THEN 'Time Supply - Issues'         WHEN 'E'  THEN 'Time Supply - Seasonal'         ELSE ril.REPL_METHOD     END                                                   AS \"Replenishment Method Description\",     ril.STOCK_CAT                                         AS \"Stock Category\",     CASE ril.STOCK_CAT         WHEN 'C' THEN 'Cross-Docked'         WHEN 'D' THEN 'Direct to Store'         WHEN 'L' THEN 'WH/Cross Link'         WHEN 'W' THEN 'Warehouse Stocked'         WHEN 'X' THEN 'PO Cross-link'         ELSE ril.STOCK_CAT     END                                                   AS \"Stock Category Description\",     ril.REPL_ORDER_CTRL                                   AS \"Order Control\",     ril.NON_SCALING_IND                                   AS \"Scaling Exempt Indicator\",     ril.MAX_SCALE_VALUE                                   AS \"Maximum Scale Amount\",     ril.PRIMARY_PACK_NO                                   AS \"Primary Replenishment Pack\",      ils.STOCK_ON_HAND                                     AS \"Pack Current Stock on Hand\",     ils.AV_COST                                           AS \"Pack Weighted Average Cost\",     cils.STOCK_ON_HAND                                    AS \"Component Current Stock on Hand\",      CASE         WHEN pisc.TI IS NULL OR pisc.HI IS NULL         THEN 'Set TI and HI on pack ITEM_SUPP_COUNTRY to match component values'         WHEN cisc.TI IS NULL OR cisc.HI IS NULL         THEN 'Set TI and HI on component ITEM_SUPP_COUNTRY - pack values exist'         WHEN pisc.TI != cisc.TI AND pisc.HI != cisc.HI         THEN 'Align both TI and HI on pack to match component: TI='              || cisc.TI || ', HI=' || cisc.HI         WHEN pisc.TI != cisc.TI         THEN 'Correct pack TI from ' || pisc.TI              || ' to ' || cisc.TI || ' to match component'         WHEN pisc.HI != cisc.HI         THEN 'Correct pack HI from ' || pisc.HI              || ' to ' || cisc.HI || ' to match component'         ELSE 'Verify configuration'     END                                                   AS \"Recommended Action\",      pisc.LEAD_TIME                                        AS \"Pack Lead Time\",     pisc.PICKUP_LEAD_TIME                                 AS \"Pack Pickup Lead Time\"  FROM     MFCS_RDS.RDS_WV_ITEM_MASTER              pim      JOIN  MFCS_RDS.RDS_WV_PACKITEM           pi    ON  pim.ITEM        = pi.PACK_NO      JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER        cim   ON  pi.ITEM         = cim.ITEM      JOIN  MFCS_RDS.RDS_WV_DEPS               d     ON  pim.DEPT        = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS              c     ON  pim.DEPT        = c.DEPT                                                    AND  pim.CLASS       = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS           sc    ON  pim.DEPT        = sc.DEPT                                                    AND  pim.CLASS       = sc.CLASS                                                    AND  pim.SUBCLASS    = sc.SUBCLASS      JOIN  MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY pisc  ON  pim.ITEM        = pisc.ITEM                                                    AND  pisc.PRIMARY_SUPP_IND    = 'Y'                                                    AND  pisc.PRIMARY_COUNTRY_IND = 'Y'      JOIN  MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY cisc  ON  pi.ITEM         = cisc.ITEM                                                    AND  cisc.SUPPLIER  = pisc.SUPPLIER                                                    AND  cisc.PRIMARY_SUPP_IND    = 'Y'                                                    AND  cisc.PRIMARY_COUNTRY_IND = 'Y'      JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC      ril  ON  pim.ITEM        = ril.ITEM                                                    AND  ril.REPL_METHOD IS NOT NULL      JOIN  MFCS_RDS.RDS_WV_ITEM_LOC            il  ON  ril.ITEM        = il.ITEM                                                    AND  ril.LOCATION   = il.LOC                                                    AND  ril.LOC_TYPE   = il.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_SUPS            sp  ON  pisc.SUPPLIER   = sp.SUPPLIER      LEFT JOIN MFCS_RDS.RDS_WV_STORE           st  ON  ril.LOCATION    = st.STORE                                                    AND  il.LOC_TYPE    = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH              wh  ON  ril.LOCATION    = wh.WH                                                    AND  il.LOC_TYPE    = 'W'      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH   ils  ON  pim.ITEM        = ils.ITEM                                                    AND  ril.LOCATION   = ils.LOC                                                    AND  ils.LOC_TYPE   = ril.LOC_TYPE      LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  cils  ON  pi.ITEM         = cils.ITEM                                                    AND  ril.LOCATION   = cils.LOC                                                    AND  cils.LOC_TYPE  = ril.LOC_TYPE  WHERE     pim.PACK_IND        = 'Y'     AND ril.REPL_METHOD IS NOT NULL     AND il.STATUS       IN ('A', 'C')     AND pim.STATUS       = 'A'     AND (         NVL(pisc.TI, -999) != NVL(cisc.TI, -999)         OR NVL(pisc.HI, -999) != NVL(cisc.HI, -999)     )  ORDER BY     CASE         WHEN pisc.TI IS NULL OR pisc.HI IS NULL           OR cisc.TI IS NULL OR cisc.HI IS NULL         THEN 'HIGH - Missing Ti-Hi prevents pallet calculation'         WHEN ABS(NVL(pisc.TI,0)-NVL(cisc.TI,0)) &gt; 5           OR ABS(NVL(pisc.HI,0)-NVL(cisc.HI,0)) &gt; 5         THEN 'HIGH - Large variance impacts warehouse slotting'         WHEN ABS(NVL(pisc.TI,0)-NVL(cisc.TI,0)) BETWEEN 2 AND 5           OR ABS(NVL(pisc.HI,0)-NVL(cisc.HI,0)) BETWEEN 2 AND 5         THEN 'MEDIUM - Moderate variance, review required'         ELSE 'LOW - Minor variance, monitor'     END,     ABS(NVL(pisc.TI, 0) - NVL(cisc.TI, 0))         + ABS(NVL(pisc.HI, 0) - NVL(cisc.HI, 0)) DESC,     d.DEPT_NAME,     pim.ITEM_DESC,     CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END</ds:dbquery><ds:target_type>Oracle 12c</ds:target_type><ds:object_name/></ds:dataptr><ds:columns><ds:column><ds:name>Report Date</ds:name><ds:datatype>timestamp</ds:datatype></ds:column><ds:column><ds:name>Department Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Department Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class Number</ds:name><ds:datatype>number</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Class Name</ds:name><ds:datatype>varchar(120)</ds:datatype><ds:nullable>false</ds:nullable></ds:column><ds:column><ds:name>Subclass Number</ds