\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Supplier ID\"],\"expressionSourceColumns\":[\"Supplier ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Supplier ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Supplier ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"3\"},{\"id\":\"5\",\"type\":\"PROPERTY_CHANGE\",\"sourceColumns\":[\"Location ID\"],\"expressionSourceColumns\":[\"Location ID\"],\"outputColumns\":[],\"options\":{\"outputColumnAggrRule\":\"none\",\"outputColumnDisplayName\":\"Location ID\",\"outputColumnRole\":\"Attribute\",\"afterColumn\":\"Location ID\"},\"applied\":true,\"inplace\":true,\"rename\":false,\"allowEdit\":false,\"generatesOutputColumns\":false,\"unsavedTransform\":false,\"parentId\":\"4\"}],\"recommendations\":[],\"dataSubsetInfos\":{\"queryEditMode\":1,\"filterbarSettings\":{},\"uiSqlStatement\":\"

-- ── Query 2 ────────────────────────────────────────────────────────────
SELECT\\n    TRUNC(SYSDATE)                                        AS \\\"Report Date\\\",\\n\\n    pim.DEPT                                              AS \\\"Department Number\\\",\\n    d.DEPT_NAME                                           AS \\\"Department Name\\\",\\n    pim.CLASS                                             AS \\\"Class Number\\\",\\n    c.CLASS_NAME                                          AS \\\"Class Name\\\",\\n    pim.SUBCLASS                                          AS \\\"Subclass Number\\\",\\n    sc.SUB_NAME                                           AS \\\"Subclass Name\\\",\\n\\n    pim.ITEM                                              AS \\\"Pack Item ID\\\",\\n    pim.ITEM_DESC                                         AS \\\"Pack Item Description\\\",\\n    pim.PACK_IND                                          AS \\\"Pack Indicator\\\",\\n    pim.STATUS                                            AS \\\"Pack Status\\\",\\n\\n    pi.ITEM                                               AS \\\"Component Item ID\\\",\\n    cim.ITEM_DESC                                         AS \\\"Component Item Description\\\",\\n    pi.PACK_QTY                                           AS \\\"Component Quantity in Pack\\\",\\n    cim.STANDARD_UOM                                      AS \\\"Component Unit of Measure\\\",\\n\\n    pisc.SUPPLIER                                         AS \\\"Supplier ID\\\",\\n    sp.SUP_NAME                                           AS \\\"Supplier Name\\\",\\n    pisc.ORIGIN_COUNTRY_ID                                AS \\\"Origin Country\\\",\\n\\n    pisc.TI                                               AS \\\"Pack Tier\\\",\\n    pisc.HI                                               AS \\\"Pack High\\\",\\n    pisc.SUPP_PACK_SIZE                                   AS \\\"Pack Supplier Pack Size\\\",\\n    pisc.INNER_PACK_SIZE                                  AS \\\"Pack Inner Pack Size\\\",\\n    NVL(pisc.TI, 0) * NVL(pisc.HI, 0)\\n        * NVL(pisc.SUPP_PACK_SIZE, 1)                     AS \\\"Pack Pallet Multiple\\\",\\n\\n    cisc.TI                                               AS \\\"Component Tier\\\",\\n    cisc.HI                                               AS \\\"Component High\\\",\\n    cisc.SUPP_PACK_SIZE                                   AS \\\"Component Supplier Pack Size\\\",\\n    cisc.INNER_PACK_SIZE                                  AS \\\"Component Inner Pack Size\\\",\\n    NVL(cisc.TI, 0) * NVL(cisc.HI, 0)\\n        * NVL(cisc.SUPP_PACK_SIZE, 1)                     AS \\\"Component Pallet Multiple\\\",\\n\\n    NVL(pisc.TI, 0) - NVL(cisc.TI, 0)                    AS \\\"Tier Variance\\\",\\n    NVL(pisc.HI, 0) - NVL(cisc.HI, 0)                    AS \\\"High Variance\\\",\\n    (NVL(pisc.TI, 0) * NVL(pisc.HI, 0) * NVL(pisc.SUPP_PACK_SIZE, 1))\\n    - (NVL(cisc.TI, 0) * NVL(cisc.HI, 0) * NVL(cisc.SUPP_PACK_SIZE, 1))\\n                                                          AS \\\"Pallet Multiple Variance\\\",\\n\\n    CASE\\n        WHEN pisc.TI IS NULL OR pisc.HI IS NULL\\n        THEN 'PACK TI-HI NOT SET'\\n        WHEN cisc.TI IS NULL OR cisc.HI IS NULL\\n        THEN 'COMPONENT TI-HI NOT SET'\\n        WHEN pisc.TI != cisc.TI AND pisc.HI != cisc.HI\\n        THEN 'BOTH TI AND HI MISMATCH'\\n        WHEN pisc.TI != cisc.TI AND pisc.HI  = cisc.HI\\n        THEN 'TI MISMATCH ONLY'\\n        WHEN pisc.TI  = cisc.TI AND pisc.HI != cisc.HI\\n        THEN 'HI MISMATCH ONLY'\\n        ELSE 'MISMATCH DETECTED'\\n    END                                                  AS \\\"Mismatch Type\\\",\\n\\n    CASE\\n        WHEN pisc.TI IS NULL OR pisc.HI IS NULL\\n          OR cisc.TI IS NULL OR cisc.HI IS NULL\\n        THEN 'HIGH - Missing Ti-Hi prevents pallet calculation'\\n        WHEN ABS(NVL(pisc.TI, 0) - NVL(cisc.TI, 0)) &gt; 5\\n          OR ABS(NVL(pisc.HI, 0) - NVL(cisc.HI, 0)) &gt; 5\\n        THEN 'HIGH - Large variance impacts warehouse slotting'\\n        WHEN ABS(NVL(pisc.TI, 0) - NVL(cisc.TI, 0)) BETWEEN 2 AND 5\\n          OR ABS(NVL(pisc.HI, 0) - NVL(cisc.HI, 0)) BETWEEN 2 AND 5\\n        THEN 'MEDIUM - Moderate variance, review required'\\n        ELSE 'LOW - Minor variance, monitor'\\n    END                                                   AS severity,\\n\\n     ril.LOCATION                                          AS \\\"Location ID\\\",\\n    il.LOC_TYPE                                           AS \\\"Location Type\\\",\\n    CASE il.LOC_TYPE\\n        WHEN 'S' THEN 'Store'\\n        WHEN 'W' THEN 'Warehouse'\\n    END                                                   AS \\\"Location Type Description\\\",\\n    CASE il.LOC_TYPE\\n        WHEN 'S' THEN st.STORE_NAME\\n        WHEN 'W' THEN wh.WH_NAME\\n    END                                                   AS \\\"Location Name\\\",\\n    il.STATUS                                             AS \\\"Item Location Status\\\",\\n    CASE il.STATUS\\n        WHEN 'A' THEN 'Active'\\n        WHEN 'C' THEN 'Discontinued'\\n        WHEN 'I' THEN 'Inactive'\\n        WHEN 'D' THEN 'Delete'\\n    END                                                   AS \\\"Item Location Status Description\\\",\\n\\n    ril.REPL_METHOD                                       AS \\\"Replenishment Method\\\",\\n    CASE ril.REPL_METHOD\\n        WHEN 'C'  THEN 'Constant'\\n        WHEN 'D'  THEN 'Dynamic'\\n        WHEN 'F'  THEN 'Floating Point'\\n        WHEN 'M'  THEN 'Min/Max'\\n        WHEN 'T'  THEN 'Time Supply'\\n        WHEN 'SO' THEN 'Store Orders'\\n        WHEN 'DI' THEN 'Dynamic - Issues'\\n        WHEN 'S'  THEN 'Dynamic - Seasonal'\\n        WHEN 'TI' THEN 'Time Supply - Issues'\\n        WHEN 'E'  THEN 'Time Supply - Seasonal'\\n        ELSE ril.REPL_METHOD\\n    END                                                   AS \\\"Replenishment Method Description\\\",\\n    ril.STOCK_CAT                                         AS \\\"Stock Category\\\",\\n    CASE ril.STOCK_CAT\\n        WHEN 'C' THEN 'Cross-Docked'\\n        WHEN 'D' THEN 'Direct to Store'\\n        WHEN 'L' THEN 'WH/Cross Link'\\n        WHEN 'W' THEN 'Warehouse Stocked'\\n        WHEN 'X' THEN 'PO Cross-link'\\n        ELSE ril.STOCK_CAT\\n    END                                                   AS \\\"Stock Category Description\\\",\\n    ril.REPL_ORDER_CTRL                                   AS \\\"Order Control\\\",\\n    ril.NON_SCALING_IND                                   AS \\\"Scaling Exempt Indicator\\\",\\n    ril.MAX_SCALE_VALUE                                   AS \\\"Maximum Scale Amount\\\",\\n    ril.PRIMARY_PACK_NO                                   AS \\\"Primary Replenishment Pack\\\",\\n\\n    ils.STOCK_ON_HAND                                     AS \\\"Pack Current Stock on Hand\\\",\\n    ils.AV_COST                                           AS \\\"Pack Weighted Average Cost\\\",\\n    cils.STOCK_ON_HAND                                    AS \\\"Component Current Stock on Hand\\\",\\n\\n    CASE\\n        WHEN pisc.TI IS NULL OR pisc.HI IS NULL\\n        THEN 'Set TI and HI on pack ITEM_SUPP_COUNTRY to match component values'\\n        WHEN cisc.TI IS NULL OR cisc.HI IS NULL\\n        THEN 'Set TI and HI on component ITEM_SUPP_COUNTRY - pack values exist'\\n        WHEN pisc.TI != cisc.TI AND pisc.HI != cisc.HI\\n        THEN 'Align both TI and HI on pack to match component: TI='\\n             || cisc.TI || ', HI=' || cisc.HI\\n        WHEN pisc.TI != cisc.TI\\n        THEN 'Correct pack TI from ' || pisc.TI\\n             || ' to ' || cisc.TI || ' to match component'\\n        WHEN pisc.HI != cisc.HI\\n        THEN 'Correct pack HI from ' || pisc.HI\\n             || ' to ' || cisc.HI || ' to match component'\\n        ELSE 'Verify configuration'\\n    END                                                   AS \\\"Recommended Action\\\",\\n\\n    pisc.LEAD_TIME                                        AS \\\"Pack Lead Time\\\",\\n    pisc.PICKUP_LEAD_TIME                                 AS \\\"Pack Pickup Lead Time\\\"\\n\\nFROM\\n    MFCS_RDS.RDS_WV_ITEM_MASTER              pim\\n\\n    JOIN  MFCS_RDS.RDS_WV_PACKITEM           pi    ON  pim.ITEM        = pi.PACK_NO\\n\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER        cim   ON  pi.ITEM         = cim.ITEM\\n\\n    JOIN  MFCS_RDS.RDS_WV_DEPS               d     ON  pim.DEPT        = d.DEPT\\n    JOIN  MFCS_RDS.RDS_WV_CLASS              c     ON  pim.DEPT        = c.DEPT\\n                                                   AND  pim.CLASS       = c.CLASS\\n    JOIN  MFCS_RDS.RDS_WV_SUBCLASS           sc    ON  pim.DEPT        = sc.DEPT\\n                                                   AND  pim.CLASS       = sc.CLASS\\n                                                   AND  pim.SUBCLASS    = sc.SUBCLASS\\n\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY pisc  ON  pim.ITEM        = pisc.ITEM\\n                                                   AND  pisc.PRIMARY_SUPP_IND    = 'Y'\\n                                                   AND  pisc.PRIMARY_COUNTRY_IND = 'Y'\\n\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_SUPP_COUNTRY cisc  ON  pi.ITEM         = cisc.ITEM\\n                                                   AND  cisc.SUPPLIER  = pisc.SUPPLIER\\n                                                   AND  cisc.PRIMARY_SUPP_IND    = 'Y'\\n                                                   AND  cisc.PRIMARY_COUNTRY_IND = 'Y'\\n\\n    JOIN  MFCS_RDS.RDS_WV_REPL_ITEM_LOC      ril  ON  pim.ITEM        = ril.ITEM\\n                                                   AND  ril.REPL_METHOD IS NOT NULL\\n\\n    JOIN  MFCS_RDS.RDS_WV_ITEM_LOC            il  ON  ril.ITEM        = il.ITEM\\n                                                   AND  ril.LOCATION   = il.LOC\\n                                                   AND  ril.LOC_TYPE   = il.LOC_TYPE\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_SUPS            sp  ON  pisc.SUPPLIER   = sp.SUPPLIER\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_STORE           st  ON  ril.LOCATION    = st.STORE\\n                                                   AND  il.LOC_TYPE    = 'S'\\n    LEFT JOIN MFCS_RDS.RDS_WV_WH              wh  ON  ril.LOCATION    = wh.WH\\n                                                   AND  il.LOC_TYPE    = 'W'\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH   ils  ON  pim.ITEM        = ils.ITEM\\n                                                   AND  ril.LOCATION   = ils.LOC\\n                                                   AND  ils.LOC_TYPE   = ril.LOC_TYPE\\n\\n    LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  cils  ON  pi.ITEM         = cils.ITEM\\n                                                   AND  ril.LOCATION   = cils.LOC\\n                                                   AND  cils.LOC_TYPE  = ril.LOC_TYPE\\n\\nWHERE\\n    pim.PACK_IND        = 'Y'\\n    AND ril.REPL_METHOD IS NOT NULL\\n    AND il.STATUS       IN ('A', 'C')\\n    AND pim.STATUS       = 'A'\\n    AND (\\n        NVL(pisc.TI, -999) != NVL(cisc.TI, -999)\\n        OR NVL(pisc.HI, -999) != NVL(cisc.HI, -999)\\n    )\\n\\nORDER BY\\n    CASE\\n        WHEN pisc.TI IS NULL OR pisc.HI IS NULL\\n          OR cisc.TI IS NULL OR cisc.HI IS NULL\\n        THEN 'HIGH - Missing Ti-Hi prevents pallet calculation'\\n        WHEN ABS(NVL(pisc.TI,0)-NVL(cisc.TI,0)) &gt; 5\\n          OR ABS(NVL(pisc.HI,0)-NVL(cisc.HI,0)) &gt; 5\\n        THEN 'HIGH - Large variance impacts warehouse slotting'\\n        WHEN ABS(NVL(pisc.TI,0)-NVL(cisc.TI,0)) BETWEEN 2 AND 5\\n          OR ABS(NVL(pisc.HI,0)-NVL(cisc.HI,0)) BETWEEN 2 AND 5\\n        THEN 'MEDIUM - Moderate variance, review required'\\n        ELSE 'LOW - Minor variance, monitor'\\n    END,\\n    ABS(NVL(pisc.TI, 0) - NVL(cisc.TI, 0))\\n        + ABS(NVL(pisc.HI, 0) - NVL(cisc.HI, 0)) DESC,\\n    d.DEPT_NAME,\\n    pim.ITEM_DESC,\\n    CASE il.LOC_TYPE WHEN 'S' THEN st.STORE_NAME WHEN 'W' THEN wh.WH_NAME END;\"},\"editorCurrentState\":false,\"joins\":{\"tables\":[]}}</ds:uiOptions><ds:version>v5</ds:version></ds:datasetImportOptions>","business-model":"\"\"","active":true,"custom-attrs":"{\"src_parquet_verified\":\"true\"}","description":"External dataset","display-name":"Manual Query","locale":"sys","is-user-striped":false,"file-length":0,"type":"sql","properties-last-modified":"2026-07-14T05:51:16.647+0000","connection-namespace":"disadmin_disadmin_APPID","private-connection":false,"credential-exists":true,"connection-name":"Remote RDS MFCS Connection","provider-type":"db","provider-name":"oracle","sso-enabled":false,"datamodelname":"'ReCommon'.'RPT_073_TiHi_Mismatch_Detail'","parent-namespace":"ReCommon","parent-name":"RPT_073_TiHi_Mismatch_Detail","data-access-mode":"auto","is-data-cacheable":true,"checkpoint-metadata-stale":false,"owner-guid":"ReCommon","is-temporary":false},"datasetType":"EMBEDDED","datamodelTwoPartName":"'ReCommon'.'RPT_073_TiHi_Mismatch_Detail'"}
